  const fillTemplate=(id)=>{const t=(adminPayload?.templates||[]).find(r=>Number(r.id)===Number(id));if(!t||!plannerForm)return;clearTemplate();const E=plannerForm.elements;E.template_id.value=t.id;['name','title','event_type','category','visibility','publish_lead_minutes','restart_minutes_before','location_source','zone_id','poi_id','description','location_label','loadout_label','x','z','duration_minutes','reminder_minutes','second_reminder_minutes','capacity','discord_channel_id','location_id','loadout_id','setup_text','rules_text','announcement_text'].forEach(k=>{if(E[k])setFriendlyValue(E[k],t[k]??'');});if(E.reward_xp)E.reward_xp.value=t.attendance_xp||0;if(E.reward_money)E.reward_money.value=t.attendance_money||0;if(E.winner_reward_xp)E.winner_reward_xp.value=t.winner_xp||0;if(E.winner_reward_money)E.winner_reward_money.value=t.winner_money||0;if(E.reward_categories)E.reward_categories.value=rewardLines(t.reward_categories);if(E.image_url)E.image_url.value=t.banner_url||'';E.signup_enabled.checked=Boolean(t.signup_enabled);E.announce_on_schedule.checked=Boolean(t.announce_on_schedule);E.ping_everyone.checked=Boolean(t.ping_everyone);E.enabled.checked=Boolean(t.enabled);setPresetSelection(t.event_type||'');syncLocationFields();qs('[data-event-editor-title]').textContent=`Edit Reusable Plan: ${t.name}`;qs('[data-event-advanced]').open=true;plannerForm.scrollIntoView({behavior:'smooth',block:'start'});};
